fr.kazepoy.fhir.fml.FhirFmlTransformStep.mapSource:
map "http://example.org/fhir/StructureMap/OruPidToPatient" = "OruPidToPatient"

uses "https://openintegrationengine.org/fhir/StructureDefinition/OieMessage" alias OieMessage as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group OruPidToPatient(source src : OieMessage, target patient : Patient) {
  src.node as pid where name = 'PID' then {
    pid.node as cx where name = 'PID.3' and node.where(position = 5 and value = 'PI').exists() then {
      cx.node as number where position = 1 -> patient.identifier as identifier then {
        number -> identifier.system = 'http://example.org/fhir/sid/ipp' "system";
        number.value as v -> identifier.value = v "identifier";
      } "ipp";
    } "identifiers";
    pid.node as xpn where name = 'PID.5' -> patient.name as name then {
      xpn.node as family where position = 1 then { family.value as v -> name.family = v "family"; } "family-name";
      xpn.node as given where position = 2 then { given.value as v -> name.given = v "given"; } "given-name";
      xpn.node as given where position = 3 then { given.value as v -> name.given = v "second-given"; } "second-given-name";
      xpn.node as type where position = 7 and value = 'L' -> name.use = 'official' "official-name";
    } "name";
    pid.node as sex where name = 'PID.8' then {
      sex.node as code where position = 1 then {
        code.value as v where v = 'F' -> patient.gender = 'female' "female";
        code.value as v where v = 'M' -> patient.gender = 'male' "male";
        code.value as v where v = 'O' -> patient.gender = 'other' "other";
        code.value as v where v = 'U' -> patient.gender = 'unknown' "unknown";
      } "gender";
    } "sex";
    pid.node as dob where name = 'PID.7' then {
      dob.node as time where position = 1 then {
        time.value as v where v.length() >= 8 -> patient.birthDate = (v.substring(0, 4) & '-' & v.substring(4, 2) & '-' & v.substring(6, 2)) "birthDate";
      } "birth-time";
    } "date-of-birth";
  } "pid";
}

map "http://example.org/fhir/oru2fhir/StructureMap/OruR01StrictToPatient" = "OruR01StrictToPatient"

uses "https://openintegrationengine.org/fhir/StructureDefinition/OieMessage" alias OieMessage as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group OruR01StrictToPatient(source src : OieMessage, target patient : Patient) {
  src.node as pr where name = 'ORU_R01.PATIENT_RESULT' then {
    pr.node as pg where name = 'ORU_R01.PATIENT' then {
      pg.node as pid where name = 'PID' then {
        pid.node as cx where name = 'PID.3' and node.where(name = 'CX.5' and value = 'PI').exists() then {
          cx.node as number where name = 'CX.1' -> patient.identifier as identifier then {
            number -> identifier.system = 'http://example.org/fhir/sid/ipp' "ipp-system";
            number.value as v -> identifier.value = v "ipp-value";
          } "ipp";
        } "identifiers";
        pid.node as xpn where name = 'PID.5' -> patient.name as name then {
          xpn.node as family where name = 'XPN.1' then {
            family.node as fn where name = 'FN.1' then { fn.value as v -> name.family = v "family"; } "fn";
          } "family-name";
          xpn.node as given where name = 'XPN.2' then { given.value as v -> name.given = v "given"; } "given-name";
          xpn.node as second where name = 'XPN.3' then { second.value as v -> name.given = v "second-given"; } "second-given-name";
          xpn.node as type where name = 'XPN.7' and value = 'L' -> name.use = 'official' "use-official";
          xpn.node as type where name = 'XPN.7' and value = 'D' -> name.use = 'usual' "use-usual";
          xpn.node as type where name = 'XPN.7' and value = 'M' -> name.use = 'maiden' "use-maiden";
        } "name";
        pid.node as sex where name = 'PID.8' then {
          sex.value as v where v = 'F' -> patient.gender = 'female' "female";
          sex.value as v where v = 'M' -> patient.gender = 'male' "male";
          sex.value as v where v = 'O' -> patient.gender = 'other' "other";
          sex.value as v where v = 'U' -> patient.gender = 'unknown' "unknown";
        } "sex";
        pid.node as dob where name = 'PID.7' then {
          dob.node as ts where name = 'TS.1' then {
            ts.value as v where v.length() >= 8 -> patient.birthDate = (v.substring(0, 4) & '-' & v.substring(4, 2) & '-' & v.substring(6, 2)) "birthDate";
          } "birth-time";
        } "date-of-birth";
      } "pid";
    } "patient-group";
  } "patient-result";
}

com.mirth.connect.plugins.javascriptstep.script:
// This destination's HL7 v2 data type provides the parsed PID.
var pid = msg['PID'][0];
var identifier = '';
for each (var cx in pid['PID.3']) {
  if (cx['PID.3.5'].toString() === 'PI') { identifier = cx['PID.3.1'].toString(); break; }
}
var name = pid['PID.5'][0];
var given = [];
if (name['PID.5.2'].toString()) given.push(name['PID.5.2'].toString());
if (name['PID.5.3'].toString()) given.push(name['PID.5.3'].toString());
var dob = pid['PID.7']['PID.7.1'].toString();
var data = {identifier: identifier, family: name['PID.5.1'].toString(), given: given,
  birthDate: dob.substring(0,4) + '-' + dob.substring(4,6) + '-' + dob.substring(6,8),
  gender: ({F:'female', M:'male', O:'other', U:'unknown'})[pid['PID.8']['PID.8.1'].toString()]};
// In Test: prepared XML (sample saved with the FML step).
msg = <patient/>;
msg.identifier = data.identifier;
msg.family = data.family;
for each (var value in data.given) msg.appendChild(<given>{value}</given>);
msg.birthDate = data.birthDate;
msg.gender = data.gender;

fr.kazepoy.fhir.fml.FhirFmlTransformStep.mapSource:
map "http://example.org/fhir/StructureMap/PreparedPatient" = "PreparedPatient"

uses "https://openintegrationengine.org/fhir/StructureDefinition/OieMessage" alias OieMessage as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group PreparedPatient(source src : OieMessage, target patient : Patient) {
  src.node as identifier where name = 'identifier' -> patient.identifier as target then {
    identifier -> target.system = 'http://example.org/fhir/sid/ipp' "system";
    identifier.value as v -> target.value = v "identifier-value";
  } "identifier";
  src -> patient.name as target then {
    src -> target.use = 'official' "use";
    src.node as family where name = 'family' then { family.value as v -> target.family = v "family-value"; } "family";
    src.node as given where name = 'given' then { given.value as v -> target.given = v "given-value"; } "given";
  } "name";
  src.node as birthDate where name = 'birthDate' then { birthDate.value as v -> patient.birthDate = v "date-value"; } "birthDate";
  src.node as gender where name = 'gender' then { gender.value as v -> patient.gender = v "gender-value"; } "gender";
}

