  gender: ({F:'female', M:'male', O:'other', U:'unknown'})[pid['PID.8']['PID.8.1'].toString()]};
// In Test: prepared JSON (sample saved with the FML step).
msg = data;

fr.kazepoy.fhir.fml.FhirFmlTransformStep.mapSource:
map "http://example.org/fhir/StructureMap/PreparedPatient" = "PreparedPatient"

uses "https://openintegrationengine.org/fhir/StructureDefinition/OieMessage" alias OieMessage as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group PreparedPatient(source src : OieMessage, target patient : Patient) {
  src.node as identifier where name = 'identifier' -> patient.identifier as target then {
    identifier -> target.system = 'http://example.org/fhir/sid/ipp' "system";
    identifier.value as v -> target.value = v "identifier-value";
  } "identifier";
  src -> patient.name as target then {
    src -> target.use = 'official' "use";
    src.node as family where name = 'family' then { family.value as v -> target.family = v "family-value"; } "family";
    src.node as given where name = 'given' then { given.value as v -> target.given = v "given-value"; } "given";
  } "name";
  src.node as birthDate where name = 'birthDate' then { birthDate.value as v -> patient.birthDate = v "date-value"; } "birthDate";
  src.node as gender where name = 'gender' then { gender.value as v -> patient.gender = v "gender-value"; } "gender";
}

com.mirth.connect.plugins.javascriptstep.script:
// Le texte contient uniquement l’IPP, extrait du PID de cette destination.
var pid = msg['PID'][0];
var identifier = '';
for each (var cx in pid['PID.3']) {
  if (cx['PID.3.5'].toString() === 'PI') { identifier = cx['PID.3.1'].toString(); break; }
}
msg = identifier;

fr.kazepoy.fhir.fml.FhirFmlTransformStep.mapSource:
map "http://example.org/fhir/StructureMap/PreparedIdentifier" = "PreparedIdentifier"

uses "https://openintegrationengine.org/fhir/StructureDefinition/OieMessage" alias OieMessage as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group PreparedIdentifier(source src : OieMessage, target patient : Patient) {
  src.value as v -> patient.identifier as identifier then {
    v -> identifier.system = 'http://example.org/fhir/sid/ipp' "system";
    v -> identifier.value = v "value";
  } "identifier";
}
